CREATE TABLE paper_labels (id INTEGER PRIMARY KEY, paper_id INTEGER NOT NULL REFERENCES paper_versions(id), version INTEGER NOT NULL, label TEXT NOT NULL CHECK(label IN ('优秀','普通','待评')), confirmed_by TEXT NOT NULL, basis TEXT NOT NULL, entered_by INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, UNIQUE(paper_id,version));
CREATE TABLE paper_comparisons (id INTEGER PRIMARY KEY, target_id INTEGER NOT NULL REFERENCES paper_versions(id), year TEXT NOT NULL, snapshot TEXT NOT NULL, result TEXT NOT NULL, created_by INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
